def _load_yaml(path: Path) -> Dict[str, Any]:
    if not path.is_file():
        return {}
    try:
        import yaml  # type: ignore
    except Exception:  # noqa: BLE001
        return {}
    try:
        with path.open("r", encoding="utf-8") as f:
            out = yaml.safe_load(f)
        return out if isinstance(out, dict) else {}
    except Exception:  # noqa: BLE001
        return {}

