def _merge_nav_nodes(base: dict[str, Any], user: dict[str, Any]) -> dict[str, Any]:
    """Merge nav node fields: user-provided keys win; auto fills missing only."""
    out = copy.deepcopy(base)
    for key, value in user.items():
        if value is None:
            continue
        if key == "entry_refs":
