def _answer_similarity(left: str, right: str) -> float:
    """Coarse answer alignment score in [0, 1]; not byte-identical equality."""
    a = (left or "").strip().lower()
    b = (right or "").strip().lower()
    if not a and not b:
        return 1.0
    if not a or not b:
        return 0.0
    if a == b:
        return 1.0
    return round(SequenceMatcher(None, a, b).ratio(), 3)


