    return "pass" if gate.get("pass") else "needs_review"


def build_export_line(
    record: dict[str, Any],
    *,

    for key in ("ibridge_record", "record", "metrics_record"):
        nested = raw.get(key)
        if isinstance(nested, dict):
            return nested
